//go:build linux || darwin

package artifactfs

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"

	"golang.org/x/sys/unix"
)

// SnapshotBytes stores host-generated bytes (a rendered code block, synthesized
// audio) as <prep>/<name> with the same durability and privacy as Snapshot:
// 0600 file in the 0700 preparation directory, fsynced file and directory, no
// overwrite. There is no agent-owned source to re-read: the caller's buffer is
// the only truth, and the returned hash is of exactly those bytes. At most
// maxBytes are accepted.
func (b *Blobs) SnapshotBytes(prep, name string, data []byte, maxBytes int64) (snap Snapshot, err error) {
	if !blobNamePattern.MatchString(name) {
		return Snapshot{}, ErrUnsafePath
	}
	if int64(len(data)) > maxBytes {
		return Snapshot{}, ErrTooLarge
	}
	dir, err := b.openPrep(prep)
	if err != nil {
		return Snapshot{}, err
	}
	defer unix.Close(dir)
	// Blobs are write-once: the private directory has one writer, so checking
	// first is enough to refuse an accidental overwrite of a ready blob.
	var existing unix.Stat_t
	if unix.Fstatat(dir, name, &existing, unix.AT_SYMLINK_NOFOLLOW) == nil {
		return Snapshot{}, mapErrno(unix.EEXIST)
	}
	part := name + ".part"
	fd, err := unix.Openat(dir, part, unix.O_WRONLY|unix.O_CREAT|unix.O_EXCL|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0o600)
	if err != nil {
		return Snapshot{}, mapErrno(err)
	}
	crashed := false
	defer func() {
		_ = unix.Close(fd)
		if err != nil && !crashed {
			_ = unix.Unlinkat(dir, part, 0)
		}
	}()
	fail := func(e error) (Snapshot, error) {
		crashed = errors.Is(e, ErrSimulatedCrash)
		return Snapshot{}, e
	}
	for off := 0; off < len(data); {
		n, werr := unix.Write(fd, data[off:])
		if werr != nil {
			return fail(mapErrno(werr))
		}
		off += n
	}
	if ferr := b.fault("copy_end"); ferr != nil {
		return fail(ferr)
	}
	if serr := unix.Fsync(fd); serr != nil {
		return fail(mapErrno(serr))
	}
	if ferr := b.fault("after_file_fsync"); ferr != nil {
		return fail(ferr)
	}
	if rerr := unix.Renameat(dir, part, dir, name); rerr != nil {
		return fail(mapErrno(rerr))
	}
	if serr := unix.Fsync(dir); serr != nil {
		_ = unix.Unlinkat(dir, name, 0)
		return fail(mapErrno(serr))
	}
	if ferr := b.fault("after_dir_fsync"); ferr != nil {
		return fail(ferr)
	}
	sum := sha256.Sum256(data)
	return Snapshot{SHA256: hex.EncodeToString(sum[:]), Size: int64(len(data))}, nil
}
